  static List<Mosque> _buildMosques() {
    return List.generate(_rawMaps.length, (i) {
      final m = Map<String, dynamic>.from(_rawMaps[i]);
      m['id'] = i + 1;
      return Mosque.fromMap(m);
    });
  }

  static List<Mosque> getMosques() => List.from(_mosques);

  static List<Mosque> getMosquesFiltered({
    bool? hasIftar,
    bool? hasParking,
    String? searchQuery,
    String? district,
  }) {
    var list = getMosques();
    if (hasIftar == true) list = list.where((m) => m.hasIftar).toList();
    if (hasParking == true) list = list.where((m) => m.hasParking).toList();
    if (district != null && district.isNotEmpty) {
      list = list.where((m) => m.district == district).toList();
    }
    if (searchQuery != null && searchQuery.isNotEmpty) {
      final q = searchQuery;
      list = list.where((m) => m.name.contains(q) || m.district.contains(q)).toList();
    }
    return list;
  }

  static List<String> getDistricts() {
    final set = <String>{};
    for (final m in _mosques) set.add(m.district);
    return set.toList()..sort();
  }

  static Mosque? getMosque(int id) {
    try {
      return _mosques.firstWhere((m) => m.id == id);
    } catch (_) {
      return null;
    }
  }
